fn test_ldr_p_bi_field_imm9h_32_poweroftwo_0_85a00000() {
    // Encoding: 0x85A00000
    // Test LDR_P.BI__ field imm9h = 32 (PowerOfTwo)
    // Fields: imm9l=0, imm9h=32, Rn=0, Pt=0
    let encoding: u32 = 0x85A00000;
    let mut cpu = create_test_cpu();
    write_insn(&mut cpu, 0, encoding);
    // Allocated encoding; the synthetic operands may fault at runtime,
    // which still proves the instruction decodes.
    let exit = cpu.step();
    let undef = match &exit {
        Ok(CpuExit::Undefined(_)) => true,
        Err(e) => format!("{e:?}").starts_with("UndefinedInstruction"),
        _ => false,
    };
    assert!(
        !undef,
        "expected allocated encoding for {:#010X}: {:?}",
        encoding, exit
    );
}

