/// Provenance: LDR_P.BI__
/// ASL: `field combination 9`
/// Requirement: FieldExtraction { field: "combination", bit_start: 0, bit_width: 32 }
/// imm9h=32 (power of 2 (2^5 = 32))
#[test]
fn test_ldr_p_bi_combo_9_0_85a00000() {
    // Encoding: 0x85A00000
    // Test LDR_P.BI__ field combination: imm9h=32, imm9l=0, Rn=0, Pt=0
    // Fields: Pt=0, imm9l=0, imm9h=32, Rn=0
    let encoding: u32 = 0x85A00000;
    let mut cpu = create_test_cpu();
    write_insn(&mut cpu, 0, encoding);
    // Allocated encoding; the synthetic operands may fault at runtime,
    // which still proves the instruction decodes.
    let exit = cpu.step();
    let undef = match &exit {
        Ok(CpuExit::Undefined(_)) => true,
        Err(e) => format!("{e:?}").starts_with("UndefinedInstruction"),
        _ => false,
    };
    assert!(
        !undef,
        "expected allocated encoding for {:#010X}: {:?}",
        encoding, exit
    );
}

