/// Requirement: FieldExtraction { field: "combination", bit_start: 0, bit_width: 32 }
/// Zt=1 (SIMD register V1)
#[test]
fn test_ld1h_z_p_ai_s_combo_16_c000_84a0c001() {
    // Encoding: 0x84A0C001
    // Test LD1H_Z.P.AI_S field combination: imm5=0, Pg=0, Zn=0, Zt=1
    // Fields: imm5=0, Pg=0, Zt=1, Zn=0
    let encoding: u32 = 0x84A0C001;
    let mut cpu = create_test_cpu();
    write_insn(&mut cpu, 0, encoding);
    // llvm-mc: ld1h	{ z1.s }, p0/z, [z0.s]
    let exit = cpu.step();
    assert!(
        exit.is_ok() && !matches!(exit.as_ref().unwrap(), CpuExit::Undefined(_)),
        "expected allocated encoding for {:#010X}: {:?}",
        encoding,
        exit
    );
}

