/// imm4=3 (2^2 - 1 = 3)
#[test]
fn test_ldnf1d_z_p_bi_u64_combo_2_a000_a5f3a000() {
    // Encoding: 0xA5F3A000
    // Test LDNF1D_Z.P.BI_U64 field combination: imm4=3, Pg=0, Rn=0, Zt=0
    // Fields: Rn=0, Zt=0, Pg=0, imm4=3
    let encoding: u32 = 0xA5F3A000;
    let mut cpu = create_test_cpu();
    write_insn(&mut cpu, 0, encoding);
    // llvm-mc: ldnf1d	{ z0.d }, p0/z, [x0, #3, mul vl]
    let exit = cpu.step();
    assert!(
        exit.is_ok() && !matches!(exit.as_ref().unwrap(), CpuExit::Undefined(_)),
        "expected allocated encoding for {:#010X}: {:?}",
        encoding,
        exit
    );
}

