/// Requirement: FieldExtraction { field: "combination", bit_start: 0, bit_width: 32 }
/// imm4=3 (2^2 - 1 = 3)
#[test]
fn test_ld3d_z_p_bi_contiguous_combo_2_e000_a5c3e000() {
    // Encoding: 0xA5C3E000
    // Test LD3D_Z.P.BI_Contiguous field combination: imm4=3, Pg=0, Rn=0, Zt=0
    // Fields: imm4=3, Rn=0, Pg=0, Zt=0
    let encoding: u32 = 0xA5C3E000;
    let mut cpu = create_test_cpu();
    write_insn(&mut cpu, 0, encoding);
    // llvm-mc: ld3d	{ z0.d - z2.d }, p0/z, [x0, #9, mul vl]
    let exit = cpu.step();
    assert!(
        exit.is_ok() && !matches!(exit.as_ref().unwrap(), CpuExit::Undefined(_)),
        "expected allocated encoding for {:#010X}: {:?}",
        encoding,
        exit
    );
}

