/// Stack pointer (SP) - may require alignment
#[test]
fn test_ld2h_z_p_bi_contiguous_special_rn_31_stack_pointer_sp_may_require_alignment_57344_a4a1e3e0()
{
    // Encoding: 0xA4A1E3E0
    // Test LD2H_Z.P.BI_Contiguous special value Rn = 31 (Stack pointer (SP) - may require alignment)
    // Fields: Zt=0, imm4=1, Pg=0, Rn=31
    let encoding: u32 = 0xA4A1E3E0;
    let mut cpu = create_test_cpu();
    write_insn(&mut cpu, 0, encoding);
    // llvm-mc: ld2h	{ z0.h, z1.h }, p0/z, [sp, #2, mul vl]
    let exit = cpu.step();
    assert!(
        exit.is_ok() && !matches!(exit.as_ref().unwrap(), CpuExit::Undefined(_)),
        "expected allocated encoding for {:#010X}: {:?}",
        encoding,
        exit
    );
}

