/// Requirement: FieldExtraction { field: "combination", bit_start: 0, bit_width: 32 }
/// imm4=7 (immediate midpoint (7))
#[test]
fn test_ld1h_z_p_bi_u64_combo_4_a000_a4e7a000() {
    // Encoding: 0xA4E7A000
    // Test LD1H_Z.P.BI_U64 field combination: imm4=7, Pg=0, Rn=0, Zt=0
    // Fields: Rn=0, imm4=7, Zt=0, Pg=0
    let encoding: u32 = 0xA4E7A000;
    let mut cpu = create_test_cpu();
    write_insn(&mut cpu, 0, encoding);
    // llvm-mc: ld1h	{ z0.d }, p0/z, [x0, #7, mul vl]
    let exit = cpu.step();
    assert!(
        exit.is_ok() && !matches!(exit.as_ref().unwrap(), CpuExit::Undefined(_)),
        "expected allocated encoding for {:#010X}: {:?}",
        encoding,
        exit
    );
}

